import{z as i,x as l,o as e,c as s,q as t,j as r,D as E,d as n,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"发行方视角：对冲与风险","description":"","frontmatter":{"title":"发行方视角：对冲与风险","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-issuer-hedging.md","filePath":"quant/ot-issuer-hedging.md","lastUpdated":1791063341000}'),d={name:"quant/ot-issuer-hedging.md"};function p(m,a,h,c,u,g){const A=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="发行方视角-对冲与风险" tabindex="-1">发行方视角：对冲与风险 <a class="header-anchor" href="#发行方视角-对冲与风险" aria-label="Permalink to &quot;发行方视角：对冲与风险&quot;">​</a></h1><div class="epigraph"><p>发行结构化产品不是承销一次卖断，是开一本与投资者方向相反的账本；发行价差是对冲成本、资金成本与信用成本之后剩下的数，不是发行之前就锁定的利润。</p><footer>—— 据 Leland, Journal of Finance, 1985 与场外衍生品做市实务整理</footer></div><p><a href="/quant/ot-barrier-portfolios">上一课</a>把账本上的障碍按标的、水平与时钟聚合成一张暴露地图。产品解剖三课走完，本课转入发行方：雪球与 FCN 的负债挂上自己的账本之后，怎么对冲、成本从哪来、盈亏怎么归因。市场层面发行台群体行为对价格的反馈，<a href="/quant/snowball-dealer-hedging">对冲商的堆积</a>已经写过；本课止于单一发行台，后课的法律与信用层默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发行有两种模式：卖断（back-to-back，发行同时把结构原样转手给对冲商，价差一次性收讫）与留存账本（发行方自己持有反向头寸并动态对冲）。卖断模式下发行方只承担文档与信用，留存模式下发行方持有的是投资者的负债端：delta、gamma、vega、gap 全部反向落在自己账上。缺口是把发行利润当已锁定收益：留存账本的利润是逐日对冲出来的，对冲频率、工具与残差处理每一环都在改写它。错在哪一步、剩多少，要靠归因回答，不能靠发行时刻的价差回答。</p><p><span class="marginnote">术语翻译：back-to-back（卖断）就是「转手」——刚跟投资者签完合约，转头找对冲商签一张条款镜像的合约对冲掉，自己只赚中间价差。它像不压货的二道贩子；留存账本则像自己囤货的经营户，赚的是存货管理的功夫钱，也担囤错的风险。</span></p>',6)),(e(),r(o,null,{default:E(()=>[B(A,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISS%5B%22%E5%8F%91%E8%A1%8C%E4%B8%80%E7%AC%94%E9%9B%AA%E7%90%83%22%5D%20--%3E%20B1%5B%22%E5%8D%96%E6%96%AD%20back-to-back%22%5D%0A%20%20ISS%20--%3E%20B2%5B%22%E7%95%99%E5%AD%98%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20B1%20--%3E%20C1%5B%22%E8%BD%AC%E6%89%8B%E5%AF%B9%E5%86%B2%E5%95%86%20%E4%BB%B7%E5%B7%AE%E4%B8%80%E6%AC%A1%E6%94%B6%E8%AE%AB%22%5D%0A%20%20C1%20--%3E%20R1%5B%22%E5%8F%AA%E6%89%BF%E6%8B%85%E6%96%87%E6%A1%A3%E4%B8%8E%E5%AF%B9%E6%89%8B%E4%BF%A1%E7%94%A8%22%5D%0A%20%20B2%20--%3E%20C2%5B%22%E8%87%AA%E6%8C%81%E5%8F%8D%E5%90%91%E5%A4%B4%E5%AF%B8%20%E5%8A%A8%E6%80%81%E5%AF%B9%E5%86%B2%22%5D%0A%20%20C2%20--%3E%20R2%5B%22delta%20gamma%20vega%20gap%20%E5%85%A8%E5%9C%A8%E8%87%AA%E5%B7%B1%E8%B4%A6%E4%B8%8A%22%5D%0A%20%20R2%20--%3E%20P%5B%22%E5%88%A9%E6%B6%A6%20%3D%20c%E2%88%92c*%20%E9%80%90%E6%97%A5%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>留存账本按三步走。第一步，负债分解：把发行负债的希腊按桶登记——delta 与 gamma 沿现货、vega 沿波动曲面、障碍前的不连续暴露单列 gap 桶，聚合输入正是<a href="/quant/ot-barrier-portfolios">上一课</a>的障碍地图。第二步，工具映射：delta 用标的、期货与 ETF，vega 用场内期权，缺口用静态条带加现金垫；每条腿写出可得性与失配——场内行权价与到期是离散的，场外条款是连续的。第三步，执行纪律：对冲频率与观察网格对齐，观察日前收紧带宽、障碍远离时放松，这是<a href="/quant/delta-hedge-freq">离散对冲频率</a>立的口径；隔夜跳空单列情景，沿<a href="/quant/overnight-gap-hedge">隔夜跳空对冲</a>的两列报告——按当前频率的流量，与停手后的观察日缺口。</p>',2)),(e(),r(o,null,{default:E(()=>[B(A,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%8F%91%E8%A1%8C%E8%B4%9F%E5%80%BA%EF%BC%9A%E6%8A%95%E8%B5%84%E8%80%85%E6%96%B9%E5%90%91%E7%9A%84%E5%AF%B9%E6%89%8B%E8%B4%A6%E6%9C%AC%22%5D%20--%3E%20D%5B%22%E5%B8%8C%E8%85%8A%E6%A1%B6%EF%BC%9Adelta%20%2F%20gamma%20%2F%20vega%20%2F%20gap%22%5D%0A%20%20D%20--%3E%20H1%5B%22%E6%9C%9F%E8%B4%A7%E4%B8%8E%20ETF%EF%BC%9Adelta%22%5D%0A%20%20D%20--%3E%20H2%5B%22%E5%9C%BA%E5%86%85%E6%9C%9F%E6%9D%83%EF%BC%9Avega%22%5D%0A%20%20D%20--%3E%20H3%5B%22%E9%9D%99%E6%80%81%E6%9D%A1%E5%B8%A6%E4%B8%8E%E7%8E%B0%E9%87%91%E5%9E%AB%EF%BC%9Agap%22%5D%0A%20%20H1%20--%3E%20R1%5B%22%E5%9F%BA%E5%B7%AE%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20H2%20--%3E%20R2%5B%22%E6%9B%B2%E9%9D%A2%E5%A4%B1%E9%85%8D%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20H3%20--%3E%20R3%5B%22%E8%A1%8C%E6%9D%83%E4%BB%B7%E9%97%B4%E9%9A%94%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20R1%20--%3E%20A%5B%22%E6%97%A5%E5%BA%A6%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%9B%A0%E5%AD%90%E6%95%8F%E6%84%9F%20%E5%8A%A0%20%E6%AE%8B%E5%B7%AE%E6%A1%B6%22%5D%0A%20%20R2%20--%3E%20A%0A%20%20R3%20--%3E%20A%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发行利润的机制口径：对投资者的负债按票息 \\(c\\) 计价，对冲组合的期望成本加资金与信用成本是 \\(c^{*}\\)，留存模式的发行价差是 \\(c-c^{*}\\) 的逐日实现，不是合同签署日的数。价差为什么存在：财富端对复杂条款有支付意愿，发行台承担对冲残差与库存风险作为对价——<a href="/quant/ot-fcn">零售结构定价偏贵</a>的实证方向在此与做市逻辑接上。Leland 的机制在离散再平衡处起效：交易成本使连续复制不可达，对冲者应以按成本与频率调整过的波动率做决策，带宽是成本与风险的交换，不是技术细节。</p><p><span class="marginnote">数字实例：卖给投资者的雪球票息 \\(c=15\\%\\) 年化，模型算出的对冲加资金加信用成本 \\(c^{*}=13\\%\\)。那 2% 价差不是签署日锁定的利润——当年滑点与贴水若多吃掉 1.5%，实际只剩 0.5%；对冲做砸了，它可以是负数。</span></p><p>希腊的符号不随叙事走：敲入带附近的凸性符号取决于条款组合，<a href="/quant/vt-exotic-risk-map">奇异风控地图</a>的变号结论在账本层同样生效——同一周发行的两只雪球，降敲节奏不同，对冲方向可以相反。不这么做会错在哪：按「雪球发行人一定在跌时卖期货」的统一叙事设置对冲，等于把别人的账本当自己的。</p><p><span class="marginnote">直觉类比：对冲带宽像开车修正方向盘的频率——打得越勤，轨迹越贴路线（复制误差小），但油钱（交易成本）越高；打得太懒，一次急拐就可能错过出口（跳过障碍）。Leland 说的就是把这个频率调到成本与风险刚好平衡的那一档。</span></p><p><span class="marginnote">日度归因的残差桶必须留位置：市场因子敏感之和解释不了的部分——观察日跳变、曲面插值差、对冲执行的滑点——进了残差桶才有人看着它。残差桶持续为正或为负，先查工具映射与频率，再查模型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给单一发行台对市场价格的反馈下结论——那是<a href="/quant/snowball-dealer-hedging">堆积</a>课的聚合层；不展开信用与文档：对手违约、净额与保证金是后课缺口。对冲工具的场内约束（行权价间隔、涨跌停、竞价深度）在本课只点名，下一单元沿<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>的口径展开。限额的设置沿用情景表达：单点 gamma 限额不足以约束障碍账本，触碰概率乘损失的情景限额是<a href="/quant/omm-greeks-limits">希腊限额</a>的延伸。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发行分卖断与留存账本：留存的利润是逐日对冲实现的，不是发行价差锁定。</li><li>负债分解成希腊桶，对冲按工具映射；对冲频率与观察网格对齐，缺口单列情景。</li><li>价差机制：条款复杂性的支付意愿减对冲、资金与信用成本；离散再平衡的成本沿 Leland 口径进带宽。</li><li>凸性符号随条款走，不随叙事走；归因必须留残差桶。</li><li>出处：Leland, <em>JF</em>, 1985；聚合与情景口径沿<a href="/quant/ot-barrier-portfolios">障碍结构的组合</a>、<a href="/quant/omm-greeks-limits">希腊限额</a>与<a href="/quant/vt-exotic-risk-map">奇异风控地图</a>。</li></ul>',10))])}const _=i(d,[["render",p]]);export{f as __pageData,_ as default};
